FROM w 
WHERE c3_number = 9;

SELECT COUNT(*) 
FROM w 
WHERE c4_number > 1000;

SELECT COUNT(*) 
FROM w 
WHERE c2_number > 100000;

SELECT COUNT(*) AS count 
FROM w 
WHERE c7_number > 50;

